// Normalisasi update Telegram -> format netral-channel.
// Hanya node ini (dan node Telegram) yang khusus Telegram. Saat pindah ke WhatsApp/kirimi.id,
// cukup buat node ini menghasilkan field yang sama; node lain tidak perlu diubah.
const update = $input.first().json;

const cb = update.callback_query;
const msg = update.message;
const chat = cb ? cb.message?.chat : msg?.chat;
const from = cb ? cb.from : msg?.from;

// Hanya layani chat pribadi. Data rapor bersifat rahasia, jadi grup/kanal dan bot lain diabaikan.
if (!chat || chat.type !== 'private' || !from || from.is_bot) return [];

// ---------- Parser tanggal -> 'YYYY-MM-DD' (urutan hari-bulan-tahun, bukan format Amerika) ----------
// Salinan yang sama dipakai di node "Normalisasi Input" dan "Cocokkan Siswa"; jika diubah, ubah keduanya.
const BULAN = {
  januari: 1, jan: 1,
  februari: 2, pebruari: 2, feb: 2,
  maret: 3, mar: 3,
  april: 4, apr: 4,
  mei: 5, may: 5,
  juni: 6, jun: 6,
  juli: 7, jul: 7,
  agustus: 8, agu: 8, agt: 8, aug: 8,
  september: 9, sep: 9, sept: 9,
  oktober: 10, okt: 10, oct: 10,
  november: 11, nov: 11, nopember: 11,
  desember: 12, des: 12, dec: 12,
};

const tanggalIso = (y, m, d) => {
  if (!(y >= 1900 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return null;
  const t = new Date(Date.UTC(y, m - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) return null;
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
};
const tahun = (t) => (t.length <= 2 ? (Number(t) <= 30 ? 2000 : 1900) + Number(t) : Number(t));

const parseTanggal = (v) => {
  if (v === null || v === undefined || v === '') return null;
  // Tanggal bertipe date di Google Sheets (nomor seri; hari sejak 30 Des 1899)
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    const t = new Date(Math.round((v - 25569) * 86400000));
    return tanggalIso(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());
  }
  const s = String(v).toLowerCase();
  const pola = [
    // 2011-08-17, 2011/08/17, 2011 08 17 (juga 2011-08-17T00:00:00Z)
    [/(?<!\d)(\d{4})[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{1,2})(?!\d)/, (m) => tanggalIso(+m[1], +m[2], +m[3])],
    // 17-08-2011, 17/08/2011, 17.08.2011, 17 08 2011, 17-08-11
    [/(?<!\d)(\d{1,2})[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{4}|\d{2})(?!\d)/, (m) => tanggalIso(tahun(m[3]), +m[2], +m[1])],
    // 17 Agustus 2011, 17-Agu-2011, 17agustus2011
    [/(?<!\d)(\d{1,2})[\s\-/.]*([a-z]{3,10})[\s\-/.,]*(\d{4}|\d{2})(?!\d)/, (m) => (BULAN[m[2]] ? tanggalIso(tahun(m[3]), BULAN[m[2]], +m[1]) : null)],
    // 17082011, 20110817, 170811
    [/(?<!\d)(\d{2})(\d{2})(\d{4})(?!\d)/, (m) => tanggalIso(+m[3], +m[2], +m[1])],
    [/(?<!\d)(\d{4})(\d{2})(\d{2})(?!\d)/, (m) => tanggalIso(+m[1], +m[2], +m[3])],
    [/(?<!\d)(\d{2})(\d{2})(\d{2})(?!\d)/, (m) => tanggalIso(tahun(m[3]), +m[2], +m[1])],
  ];
  for (const [re, baca] of pola) {
    const m = s.match(re);
    const hasil = m ? baca(m) : null;
    if (hasil) return hasil;
  }
  return null;
};

// Pesan dikirim dengan parse_mode HTML, jadi teks dari pengguna harus di-escape.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const kind = cb ? 'callback' : typeof msg.text === 'string' ? 'text' : 'other';
const text = kind === 'text' ? msg.text.trim() : '';
const data = cb ? String(cb.data ?? '') : '';

// Tombol inline (callback_data) -> intent
const TOMBOL = { 'm:main': 'menu', 'm:spmb': 'spmb', 'm:lhb': 'lhb', 'c:ya': 'ya', 'c:no': 'batal' };
const PILIHAN = { 'r:intra': 'intra', 'r:kokul': 'kokul', 'r:quran': 'quran' };

// Perintah / kata yang diketik -> intent
const KATA = {
  menu: ['/start', '/menu', 'menu', 'mulai', 'start'],
  batal: ['/batal', '/cancel', 'batal', 'cancel', 'tidak', 'bukan', 'salah', 'no'],
  ya: ['ya', 'y', 'iya', 'yes', 'ok', 'oke', 'betul', 'benar'],
  spmb: ['spmb', 'ppdb'],
  lhb: ['rapor', 'raport', 'lhb', 'laporan'],
};

let intent = 'teks';
let pilih = '';

if (kind === 'callback') {
  if (PILIHAN[data]) {
    intent = 'pilih';
    pilih = PILIHAN[data];
  } else {
    intent = TOMBOL[data] || 'menu';
  }
} else if (kind === 'text') {
  const kataPertama = text.split(/\s+/)[0].toLowerCase();
  const perintah = kataPertama.startsWith('/') ? kataPertama.replace(/@.*$/, '') : '';
  const kunci = perintah || text.toLowerCase().replace(/[\s.!?,]+$/g, '');
  intent = Object.keys(KATA).find((k) => KATA[k].includes(kunci)) || 'teks';
} else {
  intent = 'lain';
}

// "NIS [spasi] tanggal lahir". Pemisah yang diterima: spasi, _, koma, titik koma, titik dua, |, / dan -.
// credNis / credDob baru terisi bila keduanya masuk akal, sehingga ketikan asal tidak memicu pembacaan Sheet.
let credNis = '';
let credDob = '';
if (intent === 'teks') {
  const m = text.replace(/^nis\b[\s:=.]*/i, '').match(/^([A-Za-z0-9]+)[\s_,;:|/\\-]+(\S.*)$/);
  const tanggal = m ? parseTanggal(m[2]) : null;
  if (m && tanggal && /^(?=.*\d)[A-Za-z0-9]{3,20}$/.test(m[1])) {
    credNis = m[1].toUpperCase();
    credDob = tanggal; // 'YYYY-MM-DD'
  }
}

return [
  {
    json: {
      channel: 'telegram',
      chatId: String(chat.id),
      sapaan: esc(from.first_name || 'Ayah/Bunda'),
      kind,
      text,
      intent,
      pilih,
      credNis,
      credDob,
      callbackId: cb ? String(cb.id) : '',
    },
  },
];

// Cocokkan NIS + tanggal lahir yang diketik pengguna dengan baris siswa dari Google Sheets.
// Input node ini = hasil "Baca Data Siswa": 0 atau 1 baris (kosong bila NIS tidak ditemukan),
// atau satu item {error: '...'} bila Google Sheets gagal diakses (node itu memakai "continue on error").
// Output: status 'error' | 'no_match' | 'match' + data siswa. Tanggal lahir TIDAK ikut dikeluarkan.
// Bila data siswa pindah ke sumber lain (database, API), cukup ganti node pembacanya dan
// pertahankan bentuk output node ini.
const inp = $('Normalisasi Input').first().json;
const semua = $input.all().map((i) => i.json);
const gagalBaca = semua.some((r) => r && Object.keys(r).length === 1 && typeof r.error === 'string');
const baris = semua.filter((r) => r && Object.keys(r).length > 0);

// ---------- Nama kolom di Sheet (huruf besar/kecil & tanda baca diabaikan) ----------
const KOLOM = {
  nis: ['nis', 'nisn', 'nomorinduk'],
  nama: ['nama', 'namasiswa', 'namalengkap'],
  kelas: ['kelas', 'rombel'],
  lahir: ['tanggallahir', 'tgllahir', 'ttl', 'lahir'],
  intra: ['intrakurikuler', 'raporintrakurikuler', 'akademik', 'raporakademik'],
  kokul: ['kokurikuler', 'raporkokurikuler', 'ekstrakurikuler', 'raporekstrakurikuler', 'ekskul'],
  quran: ['alquran', 'raporalquran', 'quran', 'raporquran'],
};

const kunciKolom = (k) => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
const ambil = (row, alias) => {
  const peta = {};
  for (const k of Object.keys(row)) peta[kunciKolom(k)] = row[k];
  for (const a of alias) if (peta[a] !== undefined && peta[a] !== null && peta[a] !== '') return peta[a];
  return '';
};
const teks = (v) => String(v ?? '').trim();
const normNis = (v) => teks(v).replace(/\s+/g, '').toUpperCase();

// ---------- ID file Google Drive (tautan atau ID mentah) ----------
const idDrive = (v) => {
  const s = teks(v);
  if (!s) return '';
  const m = s.match(/\/d\/([A-Za-z0-9_-]{10,})/) || s.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return m[1];
  return /^[A-Za-z0-9_-]{10,}$/.test(s) ? s : '';
};

// ---------- Parser tanggal -> 'YYYY-MM-DD' (urutan hari-bulan-tahun, bukan format Amerika) ----------
// Salinan yang sama dipakai di node "Normalisasi Input" dan "Cocokkan Siswa"; jika diubah, ubah keduanya.
const BULAN = {
  januari: 1, jan: 1,
  februari: 2, pebruari: 2, feb: 2,
  maret: 3, mar: 3,
  april: 4, apr: 4,
  mei: 5, may: 5,
  juni: 6, jun: 6,
  juli: 7, jul: 7,
  agustus: 8, agu: 8, agt: 8, aug: 8,
  september: 9, sep: 9, sept: 9,
  oktober: 10, okt: 10, oct: 10,
  november: 11, nov: 11, nopember: 11,
  desember: 12, des: 12, dec: 12,
};

const tanggalIso = (y, m, d) => {
  if (!(y >= 1900 && y <= 2100 && m >= 1 && m <= 12 && d >= 1 && d <= 31)) return null;
  const t = new Date(Date.UTC(y, m - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) return null;
  return `${y}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
};
const tahun = (t) => (t.length <= 2 ? (Number(t) <= 30 ? 2000 : 1900) + Number(t) : Number(t));

const parseTanggal = (v) => {
  if (v === null || v === undefined || v === '') return null;
  // Tanggal bertipe date di Google Sheets (nomor seri; hari sejak 30 Des 1899)
  if (typeof v === 'number' && v > 20000 && v < 80000) {
    const t = new Date(Math.round((v - 25569) * 86400000));
    return tanggalIso(t.getUTCFullYear(), t.getUTCMonth() + 1, t.getUTCDate());
  }
  const s = String(v).toLowerCase();
  const pola = [
    // 2011-08-17, 2011/08/17, 2011 08 17 (juga 2011-08-17T00:00:00Z)
    [/(?<!\d)(\d{4})[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{1,2})(?!\d)/, (m) => tanggalIso(+m[1], +m[2], +m[3])],
    // 17-08-2011, 17/08/2011, 17.08.2011, 17 08 2011, 17-08-11
    [/(?<!\d)(\d{1,2})[\s\-/.]+(\d{1,2})[\s\-/.]+(\d{4}|\d{2})(?!\d)/, (m) => tanggalIso(tahun(m[3]), +m[2], +m[1])],
    // 17 Agustus 2011, 17-Agu-2011, 17agustus2011
    [/(?<!\d)(\d{1,2})[\s\-/.]*([a-z]{3,10})[\s\-/.,]*(\d{4}|\d{2})(?!\d)/, (m) => (BULAN[m[2]] ? tanggalIso(tahun(m[3]), BULAN[m[2]], +m[1]) : null)],
    // 17082011, 20110817, 170811
    [/(?<!\d)(\d{2})(\d{2})(\d{4})(?!\d)/, (m) => tanggalIso(+m[3], +m[2], +m[1])],
    [/(?<!\d)(\d{4})(\d{2})(\d{2})(?!\d)/, (m) => tanggalIso(+m[1], +m[2], +m[3])],
    [/(?<!\d)(\d{2})(\d{2})(\d{2})(?!\d)/, (m) => tanggalIso(tahun(m[3]), +m[2], +m[1])],
  ];
  for (const [re, baca] of pola) {
    const m = s.match(re);
    const hasil = m ? baca(m) : null;
    if (hasil) return hasil;
  }
  return null;
};

// ---------- Pencocokan ----------
const kosong = { nis: '', nama: '', kelas: '', files: { intra: '', kokul: '', quran: '' } };
if (gagalBaca) return [{ json: { status: 'error', ...kosong } }];

const nis = normNis(inp.credNis);
const siswa = nis ? baris.find((r) => normNis(ambil(r, KOLOM.nis)) === nis) : null;
const dobSheet = siswa ? parseTanggal(ambil(siswa, KOLOM.lahir)) : null;

// Pesan yang sama untuk "NIS tidak ada" dan "tanggal lahir salah" agar NIS tidak bisa ditebak.
if (!siswa || !dobSheet || dobSheet !== inp.credDob) return [{ json: { status: 'no_match', ...kosong } }];

return [
  {
    json: {
      status: 'match',
      nis,
      nama: teks(ambil(siswa, KOLOM.nama)),
      kelas: teks(ambil(siswa, KOLOM.kelas)),
      files: {
        intra: idDrive(ambil(siswa, KOLOM.intra)),
        kokul: idDrive(ambil(siswa, KOLOM.kokul)),
        quran: idDrive(ambil(siswa, KOLOM.quran)),
      },
    },
  },
];

// Mesin status percakapan (netral-channel). Menentukan balasan berikutnya dan status sesi baru.
//
//   idle --(pilih rapor)--> await_cred --(NIS + tgl lahir cocok)--> await_confirm --(YA)--> kirim dokumen --> idle
//
// Sesi disimpan di Data Table "sesi_bot" (satu baris per chat) oleh node "Simpan Sesi",
// SETELAH balasan terkirim. Node ini tidak menyimpan apa pun; ia hanya mengembalikan `session`.

// ===================== KONFIGURASI (boleh diubah) =====================
const KONFIG = {
  maksGagal: 5, // maksimum data tidak cocok dalam satu jendela waktu
  jendelaMenit: 15, // panjang jendela penghitungan data tidak cocok
  kunciMenit: 15, // lama layanan rapor dikunci setelah maksGagal tercapai
  sesiMenit: 10, // batas waktu menunggu balasan pengguna di tiap langkah
  kontakAdmin: '088990090900', // dicantumkan di pesan yang mengarahkan ke admin
};
const LABEL = { intra: 'Rapor Intrakurikuler', kokul: 'Rapor Kokurikuler', quran: "Rapor Al Qur'an" };
// ======================================================================

const ambilNode = (nama) => {
  try {
    return $(nama).first()?.json ?? null;
  } catch (e) {
    return null; // node tidak dijalankan pada eksekusi ini
  }
};

const inp = $('Normalisasi Input').first().json;
const row = ambilNode('Ambil Sesi') ?? {};
const cocok = ambilNode('Cocokkan Siswa'); // null bila pencarian siswa tidak dijalankan

const MENIT = 60 * 1000;
const sekarang = Date.now();
const iso = (ms) => new Date(ms).toISOString();
const waktu = (v) => Date.parse(v) || 0;
const h = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); // escape HTML
const bersih = (s) => String(s ?? '').replace(/[\\/:*?"<>|\r\n]+/g, ' ').replace(/\s+/g, ' ').trim();

// ---------- Teks balasan (parse_mode HTML) ----------
const PESAN = {
  mintaData: (label) =>
    `📝 <b>${h(label)}</b>\n\n` +
    `Silakan masukkan <b>NIS [spasi] tanggal lahir</b> ananda.\n\n` +
    `Contoh: <code>12345 17-08-2011</code>\n\n` +
    `Tanggal lahir ditulis hari-bulan-tahun (misalnya 17-08-2011, 17/08/2011, atau 17082011).\n` +
    `Ketik /batal untuk membatalkan.`,
  formatSalah:
    `⚠️ Format belum sesuai.\n\n` +
    `Silakan kirim <b>NIS [spasi] tanggal lahir</b>, contoh: <code>12345 17-08-2011</code>\n` +
    `Ketik /batal untuk membatalkan.`,
  tidakCocok: (sisa) =>
    `❌ Data tidak cocok.\n\n` +
    `Periksa kembali NIS dan tanggal lahir ananda, lalu kirim ulang dengan format <b>NIS [spasi] tanggal lahir</b>.\n\n` +
    `Sisa percobaan: ${sisa}`,
  terkunci: (menit) =>
    `🔒 Terlalu banyak data yang tidak cocok.\n\n` +
    `Demi keamanan data siswa, layanan rapor dikunci sementara. Silakan coba lagi dalam <b>${menit} menit</b> ` +
    `atau hubungi admin sekolah (WA ${KONFIG.kontakAdmin}).`,
  konfirmasi: (nama, kelas, label) =>
    `✅ Data ditemukan\n\n` +
    `Nama: <b>${h(nama)}</b>\nKelas: <b>${h(kelas || '-')}</b>\nDokumen: ${h(label)}\n\n` +
    `Apakah data di atas sudah benar? Ketik <b>YA</b> untuk menerima dokumen rapor, atau <b>BATAL</b> untuk membatalkan.`,
  ingatkan: (nama) =>
    `Ketik <b>YA</b> untuk menerima dokumen rapor${nama ? ` atas nama <b>${h(nama)}</b>` : ''}, ` +
    `atau <b>BATAL</b> untuk membatalkan.`,
  belumTersedia: (label, nama, kelas) =>
    `Data ditemukan atas nama <b>${h(nama)}</b> (kelas ${h(kelas || '-')}), namun dokumen <b>${h(label)}</b> belum tersedia.\n\n` +
    `Silakan hubungi admin sekolah (WA ${KONFIG.kontakAdmin}) untuk informasi lebih lanjut.`,
  gangguanData:
    `Mohon maaf, data siswa belum dapat diperiksa saat ini. Silakan coba lagi beberapa saat lagi ` +
    `atau hubungi admin sekolah (WA ${KONFIG.kontakAdmin}).`,
  dibatalkan: `Baik, proses dibatalkan. Tekan tombol di bawah atau ketik /start untuk kembali ke menu utama.`,
  sesiBerakhir:
    `⏱️ Sesi Anda telah berakhir karena terlalu lama tidak ada balasan.\n\n` +
    `Silakan pilih menu kembali dengan menekan tombol di bawah atau ketik /start.`,
};

// ---------- Sesi saat ini ----------
let s = {
  chat_id: inp.chatId,
  state: row.state || 'idle',
  rapor_type: row.rapor_type || '',
  nis: row.nis || '',
  nama: row.nama || '',
  kelas: row.kelas || '',
  file_ref: row.file_ref || '',
  fail_count: Number(row.fail_count) || 0,
  fail_since: row.fail_since || '',
  locked_until: row.locked_until || '',
  expires_at: row.expires_at || '',
};
// Kembali ke idle; data percobaan gagal & kunci sengaja dipertahankan.
const idle = (x) => ({ ...x, state: 'idle', rapor_type: '', nis: '', nama: '', kelas: '', file_ref: '', expires_at: '' });

const kedaluwarsa = s.state !== 'idle' && waktu(s.expires_at) <= sekarang;
if (kedaluwarsa) s = idle(s);

const sisaKunci = Math.ceil((waktu(s.locked_until) - sekarang) / MENIT);
const terkunci = sisaKunci > 0;
const batasSesi = () => iso(sekarang + KONFIG.sesiMenit * MENIT);

const hasil = (action, extra = {}) => [{ json: { action, chatId: inp.chatId, session: s, ...extra } }];
const teks = (text) => hasil('teks', { text });

// Catat satu data tidak cocok. Mengembalikan true bila kini terkunci.
const catatGagal = () => {
  if (!s.fail_since || sekarang - waktu(s.fail_since) > KONFIG.jendelaMenit * MENIT) {
    s.fail_since = iso(sekarang);
    s.fail_count = 0;
  }
  s.fail_count += 1;
  if (s.fail_count < KONFIG.maksGagal) return false;
  s.locked_until = iso(sekarang + KONFIG.kunciMenit * MENIT);
  s.fail_count = 0;
  s.fail_since = '';
  return true;
};

// ---------- Keputusan ----------
switch (inp.intent) {
  case 'menu':
    s = idle(s);
    return hasil('welcome');

  case 'spmb':
    s = idle(s);
    return hasil('spmb');

  case 'lhb':
    s = idle(s);
    return hasil('menu_lhb');

  case 'pilih': {
    s = idle(s);
    if (terkunci) return teks(PESAN.terkunci(sisaKunci));
    s.state = 'await_cred';
    s.rapor_type = inp.pilih;
    s.expires_at = batasSesi();
    return teks(PESAN.mintaData(LABEL[inp.pilih]));
  }

  case 'batal': {
    const adaProses = s.state !== 'idle' || kedaluwarsa;
    s = idle(s);
    return adaProses ? teks(PESAN.dibatalkan) : hasil('welcome');
  }

  case 'ya': {
    if (s.state === 'await_confirm' && s.file_ref) {
      const label = LABEL[s.rapor_type] || 'Rapor';
      const kirim = {
        fileId: s.file_ref,
        fileName: `${bersih(`${label} - ${s.nama}`)}.pdf`,
        caption: `📄 ${label}\nNama: ${s.nama}\nKelas: ${s.kelas || '-'}`,
      };
      s = idle(s); // disimpan setelah dokumen terkirim
      return hasil('send_doc', kirim);
    }
    if (s.state === 'await_cred') return teks(PESAN.formatSalah);
    if (kedaluwarsa) return teks(PESAN.sesiBerakhir);
    s = idle(s);
    return hasil('welcome');
  }

  default: {
    // intent 'teks' (ketikan bebas) atau 'lain' (stiker, foto, dst.)
    if (s.state !== 'await_cred' && s.state !== 'await_confirm') {
      if (kedaluwarsa) return teks(PESAN.sesiBerakhir);
      s = idle(s);
      return hasil('welcome');
    }

    if (terkunci) return teks(PESAN.terkunci(sisaKunci));

    // Tanpa "NIS tanggal-lahir" yang terbaca, tidak ada pencarian siswa; sesi dibiarkan apa adanya.
    if (!inp.credNis || !inp.credDob || !cocok) {
      return s.state === 'await_cred' ? teks(PESAN.formatSalah) : teks(PESAN.ingatkan(s.nama));
    }

    // Google Sheets gagal diakses: bukan salah pengguna, jadi tidak dihitung dan sesi dibiarkan agar bisa dicoba lagi.
    if (cocok.status === 'error') return teks(PESAN.gangguanData);

    // Data baru menggantikan konfirmasi sebelumnya (bila ada).
    const tipe = s.rapor_type;
    const label = LABEL[tipe] || 'Rapor';
    s = idle(s);
    s.state = 'await_cred';
    s.rapor_type = tipe;
    s.expires_at = batasSesi();

    if (cocok.status !== 'match') {
      if (catatGagal()) {
        s = idle(s);
        return teks(PESAN.terkunci(KONFIG.kunciMenit));
      }
      return teks(PESAN.tidakCocok(KONFIG.maksGagal - s.fail_count));
    }

    const file = cocok.files?.[tipe] || '';
    if (!file) {
      s = idle(s);
      return teks(PESAN.belumTersedia(label, cocok.nama, cocok.kelas));
    }
    s.state = 'await_confirm';
    s.nis = cocok.nis;
    s.nama = cocok.nama;
    s.kelas = cocok.kelas;
    s.file_ref = file;
    return hasil('confirm', { text: PESAN.konfirmasi(cocok.nama, cocok.kelas, label) });
  }
}
